const items = $input.all();

return items.map(item => {
  const task = item.json;

  const description = task.description || '';

  // Extract the Latitude & Longitude custom field.
  // const locationField = (task.custom_fields || []).find(
  //   field => field.name.toLowerCase() === 'latitude & longtitude'
  // );
  // const location = locationField?.value || '';

  const desc_location = description?.match(/Location:\s*([^\s,]+),\s*([^\s,]+)/i);
  const location = desc_location || '';

  let latitude = null;
  let longitude = null;
  if (location) {
    latitude = Number(location[1]);
    longitude = Number(location[2]);
  }

  // Extract email from the description.
  const emailMatch = task.description?.match(
    /Email:\s*([^\s]+@[^\s]+)/i
  );
  const email = emailMatch ? emailMatch[1] : null;

  // Extract phone from the description.
  const phoneMatch = description.match(
    /Phone:\s*([^\n]+)/i
  );
  const phone = phoneMatch
    ? phoneMatch[1].trim()
    : null;

  // Extract relative ID from the description.
  const relativeIdMatch = description.match(
    /Relative ID:\s*([^\n]+)/i
  );
  const relativeId = relativeIdMatch
    ? relativeIdMatch[1].trim()
    : null;

  // Extract related from the description.
  const patientMatch = description.match(
    /Patient:\s*\n?\s*([^\n]+)/i
  );

  const patientName = patientMatch
    ? patientMatch[1].trim()
    : null;
  let patientId = null;
  if (patientName) {
    const idMatch = patientName.match(/^([A-Za-z0-9-]+)\s*[—-]/);
    if (idMatch) {
      patientId = idMatch[1];
    }
  }


  return {
    json: {
      relative_task_id: task.id,
      relative_name: task.name,
      relative_id: relativeId,
      status: task.status?.status || null,

      created_at: task.date_created
        ? new Date(Number(task.date_created)).toISOString()
        : null,

      due_at: task.due_date
        ? new Date(Number(task.due_date)).toISOString()
        : null,

      email,
      phone,

      latitude,
      longitude,

      patient_id: patientId,
      patient_name: patientName,

      description,
      task_url: task.url || null,

      linked_tasks: task.linked_tasks || [],
      list_id: task.list?.id || null,
      list_name: task.list?.name || null,
    }
  };
});

const items = $input.all();

// DEMO DATE
// We'll replace this with a dynamic date after the workflow is tested.
const today = '2026-08-16';

function getDateOnly(isoString) {
  if (!isoString) return null;

  const date = new Date(isoString);

  if (Number.isNaN(date.getTime())) {
    return null;
  }

  return date.toISOString().slice(0, 10);
}

function addDays(dateString, days) {
  const date = new Date(`${dateString}T00:00:00Z`);

  if (Number.isNaN(date.getTime())) {
    return null;
  }

  date.setUTCDate(date.getUTCDate() + days);

  return date.toISOString().slice(0, 10);
}

function toClickUpTimestamp(dateString) {
  // Use noon UTC to prevent ClickUp from displaying
  // the previous calendar day because of timezone conversion.
  const date = new Date(`${dateString}T12:00:00.000Z`);

  if (Number.isNaN(date.getTime())) {
    return null;
  }

  return date.getTime();
}

const output = [];

for (const item of items) {
  const data = item.json;

  let reason = null;
  let visitDate = null;

  // --------------------------------
  // NEW RELATIVE
  // First visit = created date + 3 days
  // --------------------------------
  if (data.status === 'new listed') {

    const createdDate = getDateOnly(data.created_at);

    if (!createdDate) continue;

    const firstVisitDate = addDays(createdDate, 3);

    if (firstVisitDate === today) {
      reason = 'FIRST_VISIT_DUE';
      visitDate = firstVisitDate;
    }
  }

  // --------------------------------
  // ACTIVE RELATIVE
  // Weekly visit = due date
  // --------------------------------
  else if (data.status === 'active') {

    const dueDate = getDateOnly(data.due_at);

    if (!dueDate) continue;

    if (dueDate === today) {
      reason = 'WEEKLY_VISIT_DUE';
      visitDate = dueDate;
    }
  }

  // Ignore archived / anything else
  if (!reason) continue;

  output.push({
    json: {
      ...data,
      eligible: true,
      reason,
      today,
      visit_date: visitDate,
      visit_due_timestamp: toClickUpTimestamp(visitDate),
    }
  });
}

return output;

