const weather = $json;
const source = $('Check Visit Eligibility').item.json;

const visitDate = source.visit_date;

// Find the forecast entry for the visit date.
const index = weather.daily.time.indexOf(visitDate);

if (index === -1) {
  throw new Error(
    `Weather forecast not found for ${visitDate} at ${source.relative_name}`
  );
}

function cleanName(value) {
  if (!value) return '';

  // Example:
  // "R-0023 — Max Willson" → "Max Willson"
  // "R-004 — Laura Thompson" → "Laura Thompson"
  return value
    .replace(/^[A-Za-z0-9-]+\s*[—-]\s*/, '')
    .trim();
}

const relativeName = cleanName(source.relative_name);
const patientName = cleanName(source.patient_name);

const weatherCode = weather.daily.weather_code[index];

return {
  json: {
    relative_task_id: source.relative_task_id,
    relative_id: source.relative_id,
    relative_name: relativeName,

    patient_id: source.patient_id,
    patient_name: patientName,

    email: 'cooperangela223@gmail.com',

    latitude: source.latitude,
    longitude: source.longitude,

    visit_date: source.visit_date,
    reason: source.reason,

    weather: {
      weather_code: weatherCode,
      max_temperature_f:
        weather.daily.temperature_2m_max[index],

      min_temperature_f:
        weather.daily.temperature_2m_min[index],

      precipitation_probability:
        weather.daily.precipitation_probability_max[index],
    }
  }
};
